//! Buffered input with Minecraft's single-refill read behavior.
#![allow(dead_code)]
use std::io::{self, Read};
pub const DEFAULT_BUFFER_SIZE: usize = 8192;
pub struct FastBufferedInputStream<R>{input:R,buffer:Vec<u8>,limit:usize,position:usize}
impl<R:Read> FastBufferedInputStream<R>{pub fn new(input:R)->Self{Self::with_buffer_size(input,DEFAULT_BUFFER_SIZE)}pub fn with_buffer_size(input:R,size:usize)->Self{Self{input,buffer:vec![0;size],limit:0,position:0}}fn fill(&mut self)->io::Result<()>{self.limit=0;self.position=0;let n=self.input.read(&mut self.buffer)?;if n>0{self.limit=n;}Ok(())}fn available(&self)->usize{self.limit-self.position}pub fn read_byte(&mut self)->io::Result<Option<u8>>{if self.available()==0{self.fill()?;if self.available()==0{return Ok(None)}}let value=self.buffer[self.position];self.position+=1;Ok(Some(value))}pub fn read_array(&mut self,out:&mut[u8])->io::Result<usize>{let mut available=self.available();if available==0{if out.len()>=self.buffer.len(){return self.input.read(out)}self.fill()?;available=self.available();if available==0{return Ok(0)}}let n=out.len().min(available);out[..n].copy_from_slice(&self.buffer[self.position..self.position+n]);self.position+=n;Ok(n)}pub fn skip(&mut self,count:usize)->usize{let n=count.min(self.available());self.position+=n;n}}
impl<R:Read> Read for FastBufferedInputStream<R>{fn read(&mut self,out:&mut[u8])->io::Result<usize>{self.read_array(out)}}
#[cfg(test)]mod tests{use super::*;use std::io::Cursor;#[cfg(vibecraft_has_decompiled_sources)]#[test]fn source(){const J:&str=vibecraft_java_source!("/net/minecraft/util/FastBufferedInputStream.java");assert_eq!(J.lines().count(),99);assert!(J.contains("length >= this.buffer.length"));assert!(J.contains("return this.in.skip(count)"));}#[test]fn reads_and_skips(){let mut stream=FastBufferedInputStream::with_buffer_size(Cursor::new(vec![1,2,3,4]),2);assert_eq!(stream.read_byte().unwrap_or_else(|e|panic!("{e}")),Some(1));assert_eq!(stream.skip(1),1);let mut output=[0;2];assert_eq!(stream.read_array(&mut output).unwrap_or_else(|e|panic!("{e}")),2);assert_eq!(output,[3,4]);}}
